J.1
Schema
Below is the required JSON format for a trajectory in gray-box settings (where the trajectories can serve as
input for LLM-as-a-Judge and Agent-as-a-Judge).
{
"type": "array",
"items": {
"type": "object",
"properties": {
"step": {
"type": "integer",
"description": "The step
number in the
trajectory, 0-based."
},
"user_message": {
"type": ["string", "null"],
"description": "The
message
from the
external
user to the agent. If null,
no message
was sent."
},
"agent": {
"type": "object",
"properties": {
"thought": {
"type": "string",
"description": "The agent 's thought at this step."
},
"action": {
"type": ["string", "null"],
"description": "The agent 's action
sent to the
the agent did not take any action, for
example, when the agent has
finished
the task."
},
"agent_name": {
"type": "string",
"description": "The name of the agent
that made the action."
}
},
"required": ["thought", "action"],
"description": "Everything
related to the agent at this step."
},
"environment": {
"type": ["string", "null"],
"description": "The environment 's (shell, python
interpreter) response to
the action
